            referenceLanes.withUnsafeMutableBufferPointer { destination in
                unsafe HighwayReference.storeInterleaved2F64(a, b, destination.baseAddress!)
            }
            mismatches.check(portLanes, referenceLanes, "a: \(describe(a)), b: \(describe(b))")
        }
        mismatches.record()
